"use client";
import { ArtemisScope } from "./artemis-scope";
import View1 from "./components/content-sections/variants/02-metrics-gallery";
const variants = {"metrics-gallery":View1};
export interface ArtemisContentSectionsProps { className?: string; variant?: "metrics-gallery"; }
export function ArtemisContentSections({ className, variant = "metrics-gallery" }: ArtemisContentSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { motion, useInView, useReducedMotion } from "motion/react";
import { useRef } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
const LINES = [
    ["Less", "time", "managing."],
    ["More", "time", "moving."],
] as const;
const WORD_HIDDEN = { opacity: 0, filter: "blur(10px)", y: "24%" };
const WORD_SHOWN = { opacity: 1, filter: "blur(0px)", y: "0%" };
function reducedWordTransition(index: number) {
    return { opacity: { duration: 0.25, ease: ARTEMIS_EASE_OUT, delay: index * 0.021 } } as const;
}
function wordTransition(index: number) {
    const delay = index * 0.07;
    return {
        opacity: { duration: 0.7, ease: ARTEMIS_EASE_OUT, delay },
        filter: { duration: 0.9, ease: ARTEMIS_EASE_OUT, delay },
        y: { type: "spring", stiffness: 70, damping: 13, mass: 0.6, delay },
    } as const;
}
interface Metric {
    value: string;
    label: string;
    body: string;
    left: string;
}
const METRICS: readonly Metric[] = [
    { value: "42%", label: "Reduce repeat work", body: "Less time spent on repeat work.", left: "-0%" },
    { value: "3.6x", label: "Explore faster workflows", body: "Faster from first brief to final delivery.", left: "-100%" },
    { value: "24/7", label: "See live visibility", body: "A clear view of every moving part.", left: "-200%" },
];
const LINK_CLASS = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:hover:border-border art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:shrink-0 art:border art:border-border art:bg-background art:text-foreground art:hover:bg-muted art:h-9 art:rounded-full";
function Heading() {
    const ref = useRef<HTMLHeadingElement>(null);
    const inView = useInView(ref, { once: true, amount: 0.4 });
    const reduce = useReducedMotion();
    const shown = reduce ? { ...WORD_HIDDEN, opacity: 1 } : WORD_SHOWN;
    let index = 0;
    return (<h2 ref={ref} className="art:block art:max-w-4xl art:text-balance art:tracking-[-0.065em] art:text-4xl art:font-medium">
      {LINES.map((line) => (<span key={line.join(" ")} className="art:block">
          {line.map((word, wordIndex) => {
                const i = index++;
                return (<motion.span key={word} className="art:inline-block art:will-change-transform" initial={WORD_HIDDEN} animate={inView ? shown : WORD_HIDDEN} transition={reduce ? reducedWordTransition(i) : wordTransition(i)}>
                {word}
                {wordIndex < line.length - 1 ? (<span className="art:inline-block art:w-[0.25em] art:overflow-hidden">{"\u00A0"}</span>) : null}
              </motion.span>);
            })}
        </span>))}
    </h2>);
}
function MetricCard({ metric, index }: {
    metric: Metric;
    index: number;
}) {
    const reduce = useReducedMotion();
    return (<motion.article className="art:group art:relative art:isolate art:overflow-hidden art:rounded-3xl art:border art:border-border art:bg-background" initial={{ opacity: 0, filter: "blur(10px)", y: 28 }} whileInView={reduce ? undefined : { opacity: 1, filter: "blur(0px)", y: 0 }} viewport={{ once: true, margin: "-60px" }} transition={{ duration: 0.65, ease: ARTEMIS_EASE_OUT, delay: index * 0.09 }}>
      <div className="art:relative art:z-10 art:p-6 art:pb-0">
        <div className="art:flex art:items-center art:justify-between art:gap-4">
          <p className="art:font-medium art:text-5xl art:leading-none art:tracking-tight art:@min-[1024px]/artemis:text-6xl">{metric.value}</p>
          <motion.a className={LINK_CLASS} aria-label={metric.label} href="#" tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS}>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4 art:transition-transform art:duration-300 art:group-hover:translate-x-0.5 art:group-hover:-translate-y-0.5" aria-hidden="true">
              <path d="M7 7h10v10"/>
              <path d="M7 17 17 7"/>
            </svg>
          </motion.a>
        </div>
        <p className="art:mt-4 art:min-h-12 art:max-w-64 art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">{metric.body}</p>
      </div>
      <div className="art:relative art:mt-2 art:h-72 art:overflow-hidden art:@min-[1024px]/artemis:h-80">
        <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-x-4 art:inset-y-0 art:overflow-hidden">

          <img src="/assets/artemis/e77c0dbf503c1a11b633.webp" alt="" width="1536" height="1024" loading="lazy" decoding="async" className="art:absolute art:top-1/2 art:h-auto art:max-w-none art:-translate-y-1/2 art:mix-blend-multiply art:dark:mix-blend-screen art:dark:grayscale art:dark:invert" style={{ width: "300%", left: metric.left }}/>
          <div className="art:absolute art:inset-0 art:bg-background/5 art:dark:bg-background/10"/>
          <div className="art:absolute art:inset-x-0 art:top-0 art:h-12 art:bg-linear-to-b art:from-background art:via-background/40 art:to-transparent"/>
          <div className="art:absolute art:inset-x-0 art:bottom-0 art:h-12 art:bg-linear-to-t art:from-background art:via-background/40 art:to-transparent"/>
        </div>
      </div>
    </motion.article>);
}
export default function ContentSectionsMetricsGallery() {
    const reduce = useReducedMotion();
    return (<section className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-24 art:@min-[1024px]/artemis:px-8 art:@min-[1024px]/artemis:py-28">
      <div className="art:mx-auto art:w-full art:max-w-7xl">
        <motion.div className="art:max-w-4xl" initial={{ opacity: 0, filter: "blur(8px)", y: 18 }} whileInView={reduce ? undefined : { opacity: 1, filter: "blur(0px)", y: 0 }} viewport={{ once: true, margin: "-80px 0px" }} transition={{ duration: 0.65, ease: ARTEMIS_EASE_OUT }}>
          <p className="art:mb-5 art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.18em]">Built for momentum</p>
        </motion.div>
        <Heading />
        <div className="art:mt-10 art:grid art:gap-4 art:@min-[768px]/artemis:grid-cols-3 art:@min-[640px]/artemis:mt-12">
          {METRICS.map((metric, index) => (<MetricCard key={metric.label} metric={metric} index={index}/>))}
        </div>
      </div>
    </section>);
}
